begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('b3100000-0000-4000-8000-000000000800','synthetic-diagnostic-staff@example.test','{}'),('b3100000-0000-4000-8000-000000000801','synthetic-diagnostic-dvm@example.test','{}'),('b3100000-0000-4000-8000-000000000802','synthetic-diagnostic-admin@example.test','{}');
update profiles set is_active=true,full_name='Synthetic diagnostic reviewer' where id::text like 'b3100000-%';
insert into user_roles(user_id,role) values('b3100000-0000-4000-8000-000000000800','STAFF'),('b3100000-0000-4000-8000-000000000801','DVM'),('b3100000-0000-4000-8000-000000000802','ADMIN');
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated,service_role;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000800","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Diagnostics','+13035550188','synthetic-diagnostics@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic diagnostics dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'sibling',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic diagnostics sibling','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into data values('values','{"panel_name":"Synthetic chemistry","category":"laboratory","collected_on":"2026-10-01","reported_on":"2026-10-02","specimen":"Serum","method":"Synthetic device","source":"Manual in-house","interpretation":"Synthetic documentary findings","lab_order_id":null,"lab_order_version":null,"encounter_id":null,"encounter_version":null,"document_id":null,"document_version":null,"observations":[{"id":"b3100000-0000-4000-8000-000000000001","analyte_key":"synthetic-alt","label":"ALT","kind":"numeric","value_number":0,"value_text":null,"unit":"U/L","reference_low":1,"reference_high":100,"reference_text":"As entered","source_flag":"Recorded flag"},{"id":"b3100000-0000-4000-8000-000000000002","analyte_key":"synthetic-screen","label":"Screen","kind":"qualitative","value_number":null,"value_text":"Not detected","unit":null,"reference_low":null,"reference_high":null,"reference_text":"As reported","source_flag":""}]}');
insert into data select 'draft',save_diagnostic_panel('b3100000-0000-4000-8000-000000000050','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),null,'draft',(select v from data where k='values'));

select is(read_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet')),null::jsonb,'Draft has no PDF job');
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000801","role":"authenticated"}',true);
insert into data select 'final',save_diagnostic_panel('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),1,'finalize',(select v from data where k='values'),'Synthetic exact review');
insert into data select 'job',read_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'));
select is((select v#>>'{job,status}' from data where k='job'),'pending','Finalization atomically queues immutable version');
select is((select v#>>'{job,snapshot,diagnostic,reviewer_name}' from data where k='job'),'Synthetic diagnostic reviewer','Historical reviewer name copied');
select is((select v#>>'{job,snapshot,diagnostic,snapshot,observations,0,value_number}' from data where k='job'),'0','Snapshot preserves zero');
select is((select v->>'worker_configured' from data where k='job'),'false','Worker default off');
select is((select v->>'export_eligible' from data where k='job'),'false','Pending job never implies release readiness');
select is(read_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051',(select id from fx where k='sibling')),null::jsonb,'Wrong patient cannot read job');
select throws_ok($$select claim_diagnostic_pdf_job(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Staff cannot claim server work');
select throws_ok($$select * from diagnostic_pdf_jobs$$,'42501',null,'Staff cannot read private ledger');
select throws_ok($$select diagnostic_pdf_detail(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Private helper is not staff API');
insert into data select 'request',request_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000054','b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'),(select v#>>'{current,source_hash}' from data where k='final'));
select is(request_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000054','b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'),(select v#>>'{current,source_hash}' from data where k='final')),(select v from data where k='request'),'Exact request receipt recovers');
select throws_ok($$select request_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000054','b3100000-0000-4000-8000-000000000051',(select id from fx where k='sibling'),(select v#>>'{current,source_hash}' from data where k='final'))$$,'23505','PDF action conflicts with saved work','Wrong patient cannot recover another receipt');
reset role;set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(claim_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000061'),null::jsonb,'No commissioned worker means no claim');
reset role;
insert into diagnostic_pdf_worker_policy(renderer_sha,settings_sha,accepted_by,enabled) values(repeat('a',64),repeat('b',64),'b3100000-0000-4000-8000-000000000801',true);
set local role service_role;
insert into data select 'claim',claim_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000061');
select is((select v->>'fence' from data where k='claim'),'1','First claim gets fence one');
select is(claim_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000061'),(select v from data where k='claim'),'Lost claim reply recovers exact lease');
select is(claim_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051',gen_random_uuid()),null::jsonb,'Competing claim cannot replace live lease');
select throws_ok($$select * from diagnostic_pdf_captures$$,'42501',null,'Service cannot access byte ledger directly');
insert into data select 'capture',capture_diagnostic_pdf_bytes('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000061',1,'b3100000-0000-4000-8000-000000000801',(select v->>'source_hash' from data where k='claim'),(select v->>'snapshot_hash' from data where k='claim'),repeat('a',64),repeat('b',64),'JVBERi0xLjQKJSVFT0YK');
select is((select v->>'byte_length' from data where k='capture'),'15','SQL derives actual byte length');
select is((select v->>'sha256' from data where k='capture'),encode(sha256(decode('JVBERi0xLjQKJSVFT0YK','base64')),'hex'),'SQL hashes exact captured bytes');
select is((select v->>'validation_status' from data where k='capture'),'not_validated','Format marker never claims validation');
select is((select v->>'storage_status' from data where k='capture'),'not_uploaded','No fabricated Storage readiness');
select is((select v->>'export_eligible' from data where k='capture'),'false','Captured bytes remain unavailable for release');
select is(capture_diagnostic_pdf_bytes('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000061',1,'b3100000-0000-4000-8000-000000000801',(select v->>'source_hash' from data where k='claim'),(select v->>'snapshot_hash' from data where k='claim'),repeat('a',64),repeat('b',64),'JVBERi0xLjQKJSVFT0YK'),(select v from data where k='capture'),'Captured receipt recovers after lease closes');
select is(read_diagnostic_pdf_capture('b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'),'b3100000-0000-4000-8000-000000000801',(select v->>'source_hash' from data where k='claim'),(select v->>'snapshot_hash' from data where k='claim'))->>'base64','JVBERi0xLjQKJSVFT0YK','Recovery returns original bytes, never reserialized');
select throws_ok($$select capture_diagnostic_pdf_bytes('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000061',1,'b3100000-0000-4000-8000-000000000801',(select v->>'source_hash' from data where k='claim'),(select v->>'snapshot_hash' from data where k='claim'),repeat('a',64),repeat('b',64),'JVBERi0xLjUKJSVFT0YK')$$,'23505','Captured PDF identity and bytes are immutable','Changed byte retry fails');
select throws_ok($$select read_diagnostic_pdf_capture('b3100000-0000-4000-8000-000000000051',(select id from fx where k='sibling'),'b3100000-0000-4000-8000-000000000801',(select v->>'source_hash' from data where k='claim'),(select v->>'snapshot_hash' from data where k='claim'))$$,'42501','Active PDF request owner required','Wrong patient cannot recover byte capture');
reset role;select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000801","role":"authenticated"}',true);set local role authenticated;
select is(read_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'))#>>'{job,status}','captured_unverified','Capture phase is explicit');
select throws_ok($$select read_diagnostic_pdf_capture(gen_random_uuid(),gen_random_uuid(),auth.uid(),repeat('a',64),repeat('b',64))$$,'42501',null,'Staff cannot retrieve private server bytes');
insert into data select 'corrected_values',jsonb_set(v,'{observations,0,value_number}','2') from data where k='values';
select save_diagnostic_panel('b3100000-0000-4000-8000-000000000052','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),2,'draft',(select v from data where k='corrected_values'));
select save_diagnostic_panel('b3100000-0000-4000-8000-000000000053','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),3,'finalize',(select v from data where k='corrected_values'),'Synthetic correction review','Corrected transcription');
select is(read_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000053',(select id from fx where k='pet'))#>>'{job,status}','pending','Correction creates separate job');
reset role;select is((select count(*)::integer from diagnostic_pdf_jobs),2,'One job per immutable reviewed version');
select throws_ok($$update diagnostic_pdf_jobs set snapshot='{}' where id='b3100000-0000-4000-8000-000000000051'$$,'23514','PDF source evidence is immutable','Privileged source overwrite denied');
select throws_ok($$delete from diagnostic_pdf_captures$$,'23514','Diagnostic evidence is immutable','Byte captures cannot be deleted');
select throws_ok($$truncate diagnostic_pdf_captures$$,'23514','Diagnostic evidence is immutable','Truncate cannot erase byte evidence');
select set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
insert into data select 'claim2',claim_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000053','b3100000-0000-4000-8000-000000000062');
reset role;update diagnostic_pdf_jobs set lease_until=clock_timestamp()-interval '1 second' where id='b3100000-0000-4000-8000-000000000053';set local role service_role;
select throws_ok($$select read_diagnostic_pdf_claim('b3100000-0000-4000-8000-000000000053','b3100000-0000-4000-8000-000000000062',1,'b3100000-0000-4000-8000-000000000801')$$,'PT409','PDF claim expired or was superseded','Expired lease cannot authorize work');
insert into data select 'claim3',claim_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000053','b3100000-0000-4000-8000-000000000063');
select is((select v->>'fence' from data where k='claim3'),'2','Replacement lease increments fence');
select throws_ok($$select fail_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000053','b3100000-0000-4000-8000-000000000062',1,'b3100000-0000-4000-8000-000000000801','Old worker')$$,'PT409','PDF claim expired or was superseded','Stale worker cannot fail winner');
select fail_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000053','b3100000-0000-4000-8000-000000000063',2,'b3100000-0000-4000-8000-000000000801','Synthetic render failure');
reset role;set local role authenticated;select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000800","role":"authenticated"}',true);
insert into data select 'retry',retry_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000055','b3100000-0000-4000-8000-000000000053',(select id from fx where k='pet'),5,'Synthetic recovery');
select is((select v#>>'{job,requested_by}' from data where k='retry'),auth.uid()::text,'Staff recovery stamps actual new request owner');
select is(retry_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000055','b3100000-0000-4000-8000-000000000053',(select id from fx where k='pet'),5,'Synthetic recovery'),(select v from data where k='retry'),'Lost retry receipt recovers');
reset role;select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000802","role":"authenticated"}',true);
update profiles set is_active=false where id='b3100000-0000-4000-8000-000000000801';
set local role authenticated;select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000800","role":"authenticated"}',true);
select retry_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000056','b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'),3,'Recover after previous owner offboarding');
select is(read_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'))#>>'{capture,actor_id}','b3100000-0000-4000-8000-000000000801','Handoff preserves original capture attribution');
reset role;select set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
select is(read_diagnostic_pdf_capture('b3100000-0000-4000-8000-000000000051',(select id from fx where k='pet'),'b3100000-0000-4000-8000-000000000800',(select v->>'source_hash' from data where k='claim'),(select v->>'snapshot_hash' from data where k='claim'))->>'base64','JVBERi0xLjQKJSVFT0YK','Handoff recovers same bytes without regenerating');

reset role;select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000802","role":"authenticated"}',true);
update profiles set is_active=true where id='b3100000-0000-4000-8000-000000000801';
alter table diagnostic_panel_versions disable trigger diagnostic_pdf_enqueue_review;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000801","role":"authenticated"}',true);
insert into data select 'legacy_values',jsonb_set(v,'{observations,0,value_number}','3') from data where k='values';
select save_diagnostic_panel('b3100000-0000-4000-8000-000000000057','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),4,'draft',(select v from data where k='legacy_values'));
insert into data select 'legacy_final',save_diagnostic_panel('b3100000-0000-4000-8000-000000000058','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),5,'finalize',(select v from data where k='legacy_values'),'Synthetic historical review','Third source correction');
select is(read_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000058',(select id from fx where k='pet')),null::jsonb,'Historical reviewed version can predate job installation');
reset role;alter table diagnostic_panel_versions enable trigger diagnostic_pdf_enqueue_review;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000800","role":"authenticated"}',true);
select throws_ok($$select request_diagnostic_pdf_job(gen_random_uuid(),'b3100000-0000-4000-8000-000000000058',(select id from fx where k='pet'),repeat('d',64))$$,'PT409','Exact reviewed PDF source hash required','Historical request rejects a stale source hash');
select is(request_diagnostic_pdf_job('b3100000-0000-4000-8000-000000000059','b3100000-0000-4000-8000-000000000058',(select id from fx where k='pet'),(select v#>>'{current,source_hash}' from data where k='legacy_final'))#>>'{job,created_by}',auth.uid()::text,'Historical request creates job with actual requester attribution');
reset role;set local role anon;
select throws_ok($$select read_diagnostic_pdf_job(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Anonymous job read denied');
select throws_ok($$select claim_diagnostic_pdf_job(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Anonymous worker claim denied');
reset role;select is((select count(*)::integer from communication_outbox),0,'PDF work creates no communication');
select * from finish();rollback;
